// ---------------------------------------------------------------------------
// Mock DNSimple API Server
// ---------------------------------------------------------------------------

interface MockResponse {
  status?: number;
  body?: unknown;
  headers?: Record<string, string>;
}

type MockHandler = MockResponse | ((url: URL, count: number) => MockResponse);

interface RecordedRequest {
  method: string;
  url: URL;
  authorization: string | null;
  body: unknown;
}

/** Routes are keyed "METHOD /path"; the path excludes the API base URL. */
function startMockServer(
  routes: Record<string, MockHandler>,
): { url: string; server: Deno.HttpServer; requests: RecordedRequest[] } {
  const requests: RecordedRequest[] = [];
  const counts: Record<string, number> = {};
  const server = Deno.serve({ port: 0, onListen() {} }, async (req) => {
    const url = new URL(req.url);
    const text = await req.text();
    requests.push({
      method: req.method,
      url,
      authorization: req.headers.get("authorization"),
      body: text ? JSON.parse(text) : undefined,
    });

    const key = `${req.method} ${url.pathname}`;
    const handler = routes[key];
    if (handler === undefined) {
      return Response.json({ message: "Not found" }, { status: 404 });
    }
    counts[key] = (counts[key] ?? 0) + 1;
    const res = typeof handler === "function"
      ? handler(url, counts[key])
      : handler;
    const status = res.status ?? 200;
    if (status === 204 || res.body === undefined) {
      return new Response(null, { status, headers: res.headers });
    }
    return Response.json(res.body, { status, headers: res.headers });
  });

  const addr = server.addr as Deno.NetAddr;
  return { url: `http://localhost:${addr.port}`, server, requests };
}

function installFetchMock(mockUrl: string): () => void {
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (input, init) => {
    const reqUrl = typeof input === "string" ? input : input.toString();
    const newUrl = reqUrl
      .replace("https://api.dnsimple.com/v2", mockUrl)
      .replace("https://api.sandbox.dnsimple.com/v2", mockUrl);
    return originalFetch(newUrl, init);
  };
  return () => {
    globalThis.fetch = originalFetch;
  };
}

const GLOBAL_ARGS = {
  "apiToken": "test-token",
  "accountId": "1010",
  "environment": "production",
};

function newContext(globalArgs: Record<string, unknown> = GLOBAL_ARGS) {
  return createModelTestContext({
    globalArgs,
    definition: { id: "test-id", name: "test-model", version: 1, tags: {} },
  });
}

type Executable = {
  execute: (
    args: Record<string, unknown>,
    ctx: unknown,
  ) => Promise<{ dataHandles: unknown[] }>;
};

function run(name: string, args: Record<string, unknown>, context: unknown) {
  return (model.methods as unknown as Record<string, Executable>)[name]
    .execute(args, context);
}

/** Parse written data against the resource schema its spec names. */
function parseAgainstSchema(specName: string, data: unknown): void {
  const resource = (model.resources as unknown as Record<
    string,
    { schema: { parse: (d: unknown) => unknown } }
  >)[specName];
  assertExists(resource, `no resource spec named ${specName}`);
  resource.schema.parse(data);
}

